INSERT INTO "TutorApplications" ("Id", "UserId", "Bio", "Education", "University", "Major", "DegreeLevel", "Certifications", "Subject", "SubjectSub", "ExperienceYears", "TeachingMode", "Address", "Latitude", "Longitude", "Methodology", "Achievements", "DocumentsJson", "Status", "SubmittedAt", "RejectionReason", "ReviewedByAdminId", "ReviewedAt") VALUES
    ('b45578f6-6672-5bf5-a4a7-7f6f1e010db6', 'fe2f8134-8468-5fe1-b914-ad73accbe890', 'Tôi đã có 7 năm đồng hành cùng học viên môn Toán 12. Khởi đầu bằng bài kiểm tra ngắn, sau đó chia mục tiêu theo từng chuyên đề và sửa lỗi trực tiếp trên bài làm. Hiện tôi nhận dạy tại Hà Nội và trực tuyến.', 'Cử nhân Sư phạm Toán, Đại học Sư phạm Hà Nội', 'Đại học Sư phạm Hà Nội', 'Sư phạm Toán', 'Cử nhân', NULL, 'Toán 12', NULL, 7, 'Both', 'Hà Nội', NULL, NULL, 'Khởi đầu bằng bài kiểm tra ngắn, sau đó chia mục tiêu theo từng chuyên đề và sửa lỗi trực tiếp trên bài làm.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-252000 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-249120 minutes'),
    ('e09d556a-a187-58cf-a999-5ea026037a02', '5a5640d4-8316-5de3-91e6-12f78bd512ad', 'Tôi đã có 6 năm đồng hành cùng học viên môn IELTS. Dạy theo tiêu chí chấm điểm; mỗi buổi có bài nói ghi âm và phần nhận xét cụ thể để học viên tự luyện. Hiện tôi nhận dạy tại Hà Nội.', 'Cử nhân Ngôn ngữ Anh, Đại học Ngoại ngữ - ĐHQGHN', 'Đại học Ngoại ngữ - ĐHQGHN', 'Ngôn ngữ Anh', 'Cử nhân', NULL, 'IELTS', NULL, 6, 'Online', NULL, NULL, NULL, 'Dạy theo tiêu chí chấm điểm; mỗi buổi có bài nói ghi âm và phần nhận xét cụ thể để học viên tự luyện.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-246240 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-243360 minutes'),
    ('02cb70e7-2714-512f-9e36-6bdf9d86c3d0', '5e37dd3b-08be-5fbd-979c-1a4c5d6c4c96', 'Tôi đã có 5 năm đồng hành cùng học viên môn Vật lý 11. Dùng thí nghiệm đơn giản và sơ đồ lực để học viên hiểu hiện tượng trước khi áp dụng công thức. Hiện tôi nhận dạy tại TP. Hồ Chí Minh và trực tuyến.', 'Cử nhân Sư phạm Vật lý, Đại học Sư phạm TP.HCM', 'Đại học Sư phạm TP.HCM', 'Sư phạm Vật lý', 'Cử nhân', NULL, 'Vật lý 11', NULL, 5, 'Both', 'TP. Hồ Chí Minh', NULL, NULL, 'Dùng thí nghiệm đơn giản và sơ đồ lực để học viên hiểu hiện tượng trước khi áp dụng công thức.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-240480 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-237600 minutes'),
    ('9f7af51e-d334-5c4b-83ca-298ea407daac', '1c138fa6-b36c-501f-86e4-4aafddcd3f2d', 'Tôi đã có 8 năm đồng hành cùng học viên môn Hóa học 12. Đi từ bản chất phản ứng đến dạng bài; cuối buổi có phiếu ôn tập ngắn để kiểm tra mức độ nắm bài. Hiện tôi nhận dạy tại Hà Nội.', 'Cử nhân Sư phạm Hóa học, Đại học Sư phạm Hà Nội', 'Đại học Sư phạm Hà Nội', 'Sư phạm Hóa học', 'Cử nhân', NULL, 'Hóa học 12', NULL, 8, 'Offline', 'Hà Nội', NULL, NULL, 'Đi từ bản chất phản ứng đến dạng bài; cuối buổi có phiếu ôn tập ngắn để kiểm tra mức độ nắm bài.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-234720 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-231840 minutes'),
    ('b0f9eb8b-8a37-5d28-9e31-ee9114c9d94c', 'dc0a1d1e-a5c8-5146-92ee-258a848aa7bf', 'Tôi đã có 9 năm đồng hành cùng học viên môn Ngữ văn 9. Khuyến khích học viên tự lập luận, sau đó hướng dẫn chỉnh dàn ý và diễn đạt thay vì học thuộc văn mẫu. Hiện tôi nhận dạy tại TP. Hồ Chí Minh và trực tuyến.', 'Cử nhân Sư phạm Ngữ văn, Đại học Sư phạm TP.HCM', 'Đại học Sư phạm TP.HCM', 'Sư phạm Ngữ văn', 'Cử nhân', NULL, 'Ngữ văn 9', NULL, 9, 'Both', 'TP. Hồ Chí Minh', NULL, NULL, 'Khuyến khích học viên tự lập luận, sau đó hướng dẫn chỉnh dàn ý và diễn đạt thay vì học thuộc văn mẫu.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-228960 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-226080 minutes'),
    ('b66a2909-e699-585d-a372-2389825d6a18', '283ca06f-3334-5a58-93d1-9305c1db04ad', 'Tôi đã có 4 năm đồng hành cùng học viên môn Python cơ bản. Học qua dự án nhỏ: mỗi khái niệm được dùng ngay trong một bài tập có phản hồi về cách viết mã. Hiện tôi nhận dạy tại Đà Nẵng.', 'Cử nhân Khoa học máy tính, Đại học Bách khoa Hà Nội', 'Đại học Bách khoa Hà Nội', 'Khoa học máy tính', 'Cử nhân', NULL, 'Python cơ bản', NULL, 4, 'Online', NULL, NULL, NULL, 'Học qua dự án nhỏ: mỗi khái niệm được dùng ngay trong một bài tập có phản hồi về cách viết mã.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-223200 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-220320 minutes'),
    ('2e1a63d8-52e7-5861-91ac-6a21ef0f3794', 'd344d30d-53e4-5cb7-a284-8486f0912b95', 'Tôi đã có 5 năm đồng hành cùng học viên môn Tiếng Anh THCS. Kết hợp luyện nghe nói hằng tuần với sửa phát âm và củng cố ngữ pháp theo lỗi thực tế của học viên. Hiện tôi nhận dạy tại Hải Phòng.', 'Cử nhân Ngôn ngữ Anh, Đại học Ngoại thương', 'Đại học Ngoại thương', 'Ngôn ngữ Anh', 'Cử nhân', NULL, 'Tiếng Anh THCS', NULL, 5, 'Online', NULL, NULL, NULL, 'Kết hợp luyện nghe nói hằng tuần với sửa phát âm và củng cố ngữ pháp theo lỗi thực tế của học viên.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-217440 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-214560 minutes'),
    ('d7f88596-54e6-542c-8757-42458cf1cf5e', '778ca838-d8f4-5d60-8349-761e31ce0389', 'Tôi đã có 6 năm đồng hành cùng học viên môn Lịch sử 12. Xây dựng trục thời gian, so sánh bối cảnh và luyện câu hỏi vận dụng thay vì ghi nhớ rời rạc. Hiện tôi nhận dạy tại Huế và trực tuyến.', 'Cử nhân Sư phạm Lịch sử, Đại học Sư phạm Hà Nội', 'Đại học Sư phạm Hà Nội', 'Sư phạm Lịch sử', 'Cử nhân', NULL, 'Lịch sử 12', NULL, 6, 'Both', 'Huế', NULL, NULL, 'Xây dựng trục thời gian, so sánh bối cảnh và luyện câu hỏi vận dụng thay vì ghi nhớ rời rạc.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-211680 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-208800 minutes'),
    ('41d58a8c-38a3-5b78-a412-9d3f3a3bc58e', '597f89a0-5efe-56c5-ad90-3630c39f970a', 'Tôi đã có 2 năm đồng hành cùng học viên môn Lập trình web. Ứng tuyển với kế hoạch dạy thực hành và dự án trang web cá nhân cho người mới bắt đầu. Hiện tôi nhận dạy tại Hà Nội.', 'Cử nhân Công nghệ thông tin, Đại học Công nghệ - ĐHQGHN', 'Đại học Công nghệ - ĐHQGHN', 'Công nghệ thông tin', 'Cử nhân', NULL, 'Lập trình web', NULL, 2, 'Online', NULL, NULL, NULL, 'Ứng tuyển với kế hoạch dạy thực hành và dự án trang web cá nhân cho người mới bắt đầu.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-205920 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-203040 minutes'),
    ('ea9bcdff-889a-5e91-9843-47f4425ee0fb', 'b1e99304-5b49-5b26-85a7-748a8a495140', 'Tôi đã có 1 năm đồng hành cùng học viên môn Phương pháp tự học. Mong muốn hỗ trợ học sinh xây dựng thói quen học và theo dõi tiến độ mỗi tuần. Hiện tôi nhận dạy tại Cần Thơ và trực tuyến.', 'Cử nhân Tâm lý học giáo dục, Đại học Khoa học Xã hội và Nhân văn', 'Đại học Khoa học Xã hội và Nhân văn', 'Tâm lý học giáo dục', 'Cử nhân', NULL, 'Phương pháp tự học', NULL, 1, 'Both', 'Cần Thơ', NULL, NULL, 'Mong muốn hỗ trợ học sinh xây dựng thói quen học và theo dõi tiến độ mỗi tuần.', NULL, NULL, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-200160 minutes', NULL, 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-197280 minutes'),
    ('b2753305-a697-5992-baea-55e5824a6031', '5f4cbe11-1baf-5cc8-86ea-e68bd00941d1', 'Tôi đã có 3 năm đồng hành cùng học viên môn Vật lý 11. Đang hoàn thiện hồ sơ với bản kế hoạch dạy về điện học và bài tập thí nghiệm tại nhà. Hiện tôi nhận dạy tại Hải Dương.', 'Cử nhân Sư phạm Vật lý, Đại học Sư phạm Hà Nội', 'Đại học Sư phạm Hà Nội', 'Sư phạm Vật lý', 'Cử nhân', NULL, 'Vật lý 11', NULL, 3, 'Online', NULL, NULL, NULL, 'Đang hoàn thiện hồ sơ với bản kế hoạch dạy về điện học và bài tập thí nghiệm tại nhà.', NULL, NULL, 'Pending', CURRENT_TIMESTAMP + INTERVAL '-194400 minutes', NULL, NULL, NULL),
    ('06b9413e-34b0-5eee-9ca8-97385f5a64f7', '99ea3805-76e6-599b-8c71-fba04eb1f103', 'Tôi đã có 1 năm đồng hành cùng học viên môn IELTS. Ứng tuyển dạy IELTS nhưng chưa cung cấp chứng chỉ năng lực tiếng Anh và minh chứng giảng dạy. Hiện tôi nhận dạy tại Hà Nội.', 'Cử nhân Quản trị kinh doanh, Đại học Kinh tế Quốc dân', 'Đại học Kinh tế Quốc dân', 'Quản trị kinh doanh', 'Cử nhân', NULL, 'IELTS', NULL, 1, 'Online', NULL, NULL, NULL, 'Ứng tuyển dạy IELTS nhưng chưa cung cấp chứng chỉ năng lực tiếng Anh và minh chứng giảng dạy.', NULL, NULL, 'Rejected', CURRENT_TIMESTAMP + INTERVAL '-188640 minutes', 'Chưa cung cấp chứng chỉ tiếng Anh và minh chứng kinh nghiệm giảng dạy IELTS.', 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-185760 minutes');
