    ('97519e8b-566e-5da6-9430-51ef802f27b4', '283ca06f-3334-5a58-93d1-9305c1db04ad', 'Tôi đã có 4 năm đồng hành cùng học viên môn Python cơ bản. Học qua dự án nhỏ: mỗi khái niệm được dùng ngay trong một bài tập có phản hồi về cách viết mã. Hiện tôi nhận dạy tại Đà Nẵng.', 'Cử nhân Khoa học máy tính – Đại học Bách khoa Hà Nội', 4, 'Online', NULL, NULL, NULL, 5.00, 1, 'Ngân hàng TMCP Ngoại thương Việt Nam', 'VCB', '0011000000006', 'VŨ HOÀNG LONG'),
    ('4bacb296-0bf3-5acb-b23b-626e7e88d363', 'd344d30d-53e4-5cb7-a284-8486f0912b95', 'Tôi đã có 5 năm đồng hành cùng học viên môn Tiếng Anh THCS. Kết hợp luyện nghe nói hằng tuần với sửa phát âm và củng cố ngữ pháp theo lỗi thực tế của học viên. Hiện tôi nhận dạy tại Hải Phòng.', 'Cử nhân Ngôn ngữ Anh – Đại học Ngoại thương', 5, 'Online', NULL, NULL, NULL, 0.00, 0, 'Ngân hàng TMCP Ngoại thương Việt Nam', 'VCB', '0011000000007', 'BÙI THẢO MY'),
    ('94fee594-7505-5e77-9ab5-3bb0bce0368e', '778ca838-d8f4-5d60-8349-761e31ce0389', 'Tôi đã có 6 năm đồng hành cùng học viên môn Lịch sử 12. Xây dựng trục thời gian, so sánh bối cảnh và luyện câu hỏi vận dụng thay vì ghi nhớ rời rạc. Hiện tôi nhận dạy tại Huế và trực tuyến.', 'Cử nhân Sư phạm Lịch sử – Đại học Sư phạm Hà Nội', 6, 'Both', 'Huế', NULL, NULL, 5.00, 2, 'Ngân hàng TMCP Ngoại thương Việt Nam', 'VCB', '0011000000008', 'HOÀNG ĐỨC PHÚC'),
    ('62cd2a03-5e62-5cfe-ac64-abf5a7da35aa', '597f89a0-5efe-56c5-ad90-3630c39f970a', 'Tôi đã có 2 năm đồng hành cùng học viên môn Lập trình web. Ứng tuyển với kế hoạch dạy thực hành và dự án trang web cá nhân cho người mới bắt đầu. Hiện tôi nhận dạy tại Hà Nội.', 'Cử nhân Công nghệ thông tin – Đại học Công nghệ - ĐHQGHN', 2, 'Online', NULL, NULL, NULL, 4.50, 2, 'Ngân hàng TMCP Ngoại thương Việt Nam', 'VCB', '0011000000009', 'MAI KHÁNH LINH'),
    ('c8e6e19b-5646-5494-97ca-4661d908f4e6', 'b1e99304-5b49-5b26-85a7-748a8a495140', 'Tôi đã có 1 năm đồng hành cùng học viên môn Phương pháp tự học. Mong muốn hỗ trợ học sinh xây dựng thói quen học và theo dõi tiến độ mỗi tuần. Hiện tôi nhận dạy tại Cần Thơ và trực tuyến.', 'Cử nhân Tâm lý học giáo dục – Đại học Khoa học Xã hội và Nhân văn', 1, 'Both', 'Cần Thơ', NULL, NULL, 0.00, 0, 'Ngân hàng TMCP Ngoại thương Việt Nam', 'VCB', '0011000000010', 'NGÔ HẢI NAM');
