    ('8871ae6f-4f2e-5694-bbe2-db3170db9a4b', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'e57a5d7a-b232-5e07-b67a-303100c5f82d', 'Giải tích 12 từ nền tảng đến vận dụng', 'Lộ trình 6 buổi học 1 kèm 1 về Toán 12. Mỗi buổi gồm ôn kiến thức, thực hành và nhận xét bài làm. Gia sư Nguyễn Minh Anh điều chỉnh bài tập theo điểm mạnh, điểm cần cải thiện của học viên.', 'Hàm số và đồ thị; Nguyên hàm, tích phân; Ứng dụng đạo hàm; Luyện đề theo lỗi sai', 'Nắm được hàm số và đồ thị và tự xử lý bài tập tổng hợp trong phạm vi khóa học.', 6, 90, 1500000, 'Both', NULL, 'Published', CURRENT_TIMESTAMP + INTERVAL '-208800 minutes', CURRENT_TIMESTAMP + INTERVAL '-57600 minutes', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&fit=crop&w=1200&q=80', '[{"sessionIndex":1,"title":"Hàm số và đồ thị","description":"Học và thực hành hàm số và đồ thị; gia sư nhận xét bài làm trong buổi.","keyTopics":["Hàm số và đồ thị","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":2,"title":"Nguyên hàm, tích phân","description":"Học và thực hành nguyên hàm, tích phân; gia sư nhận xét bài làm trong buổi.","keyTopics":["Nguyên hàm, tích phân","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":3,"title":"Ứng dụng đạo hàm","description":"Học và thực hành ứng dụng đạo hàm; gia sư nhận xét bài làm trong buổi.","keyTopics":["Ứng dụng đạo hàm","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":4,"title":"Luyện đề theo lỗi sai","description":"Học và thực hành luyện đề theo lỗi sai; gia sư nhận xét bài làm trong buổi.","keyTopics":["Luyện đề theo lỗi sai","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":5,"title":"Hàm số và đồ thị","description":"Học và thực hành hàm số và đồ thị; gia sư nhận xét bài làm trong buổi.","keyTopics":["Hàm số và đồ thị","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":6,"title":"Nguyên hàm, tích phân","description":"Học và thực hành nguyên hàm, tích phân; gia sư nhận xét bài làm trong buổi.","keyTopics":["Nguyên hàm, tích phân","Bài tập có phản hồi"],"durationMinutes":90}]'::jsonb, '[{"question":"Có cần chuẩn bị trước buổi học không?","answer":"Học viên gửi mục tiêu và bài đã làm để gia sư chuẩn bị nội dung phù hợp."},{"question":"Có thể đổi lịch không?","answer":"Có thể thống nhất lại lịch trực tiếp với gia sư trước buổi học."}]'::jsonb, '["Có thiết bị hoặc không gian học phù hợp","Sẵn sàng làm bài tập sau mỗi buổi"]'::jsonb, '["Học viên muốn củng cố Toán 12","Người cần phản hồi cá nhân 1 kèm 1"]'::jsonb, '6 buổi 1 kèm 1 về Toán 12; có bài tập và nhận xét riêng.', '["Toán 12","1 kèm 1","Có lộ trình"]'::jsonb, NULL, NULL, FALSE),
    ('59360d3a-0514-520e-ba7c-5af3e7994681', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'e57a5d7a-b232-5e07-b67a-303100c5f82d', 'Ôn thi tốt nghiệp THPT môn Toán', 'Lộ trình 4 buổi học 1 kèm 1 về Toán 12. Mỗi buổi gồm ôn kiến thức, thực hành và nhận xét bài làm. Gia sư Nguyễn Minh Anh điều chỉnh bài tập theo điểm mạnh, điểm cần cải thiện của học viên.', 'Khảo sát năng lực; Các dạng vận dụng; Đề minh họa; Chiến lược phân bổ thời gian', 'Nắm được khảo sát năng lực và tự xử lý bài tập tổng hợp trong phạm vi khóa học.', 4, 90, 1200000, 'Both', NULL, 'Published', CURRENT_TIMESTAMP + INTERVAL '-205920 minutes', CURRENT_TIMESTAMP + INTERVAL '-57600 minutes', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?auto=format&fit=crop&w=1200&q=80', '[{"sessionIndex":1,"title":"Khảo sát năng lực","description":"Học và thực hành khảo sát năng lực; gia sư nhận xét bài làm trong buổi.","keyTopics":["Khảo sát năng lực","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":2,"title":"Các dạng vận dụng","description":"Học và thực hành các dạng vận dụng; gia sư nhận xét bài làm trong buổi.","keyTopics":["Các dạng vận dụng","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":3,"title":"Đề minh họa","description":"Học và thực hành đề minh họa; gia sư nhận xét bài làm trong buổi.","keyTopics":["Đề minh họa","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":4,"title":"Chiến lược phân bổ thời gian","description":"Học và thực hành chiến lược phân bổ thời gian; gia sư nhận xét bài làm trong buổi.","keyTopics":["Chiến lược phân bổ thời gian","Bài tập có phản hồi"],"durationMinutes":90}]'::jsonb, '[{"question":"Có cần chuẩn bị trước buổi học không?","answer":"Học viên gửi mục tiêu và bài đã làm để gia sư chuẩn bị nội dung phù hợp."},{"question":"Có thể đổi lịch không?","answer":"Có thể thống nhất lại lịch trực tiếp với gia sư trước buổi học."}]'::jsonb, '["Có thiết bị hoặc không gian học phù hợp","Sẵn sàng làm bài tập sau mỗi buổi"]'::jsonb, '["Học viên muốn củng cố Toán 12","Người cần phản hồi cá nhân 1 kèm 1"]'::jsonb, '4 buổi 1 kèm 1 về Toán 12; có bài tập và nhận xét riêng.', '["Toán 12","1 kèm 1","Có lộ trình"]'::jsonb, NULL, NULL, FALSE),
    ('2973d9f5-d0a7-5021-bb05-d28fb21e9c0e', '3559588e-27a9-5f80-9e24-2254454cb15e', 'f9c16ec0-8fbe-5cdc-898b-8b9ac6d03180', 'IELTS Writing Task 2: lập luận và sửa bài', 'Lộ trình 6 buổi học 1 kèm 1 về IELTS. Mỗi buổi gồm ôn kiến thức, thực hành và nhận xét bài làm. Gia sư Trần Thu Hà điều chỉnh bài tập theo điểm mạnh, điểm cần cải thiện của học viên.', 'Phân tích đề; Lập dàn ý; Phát triển đoạn văn; Sửa bài theo band descriptor', 'Nắm được phân tích đề và tự xử lý bài tập tổng hợp trong phạm vi khóa học.', 6, 90, 1800000, 'Online', NULL, 'Published', CURRENT_TIMESTAMP + INTERVAL '-203040 minutes', CURRENT_TIMESTAMP + INTERVAL '-57600 minutes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=1200&q=80', '[{"sessionIndex":1,"title":"Phân tích đề","description":"Học và thực hành phân tích đề; gia sư nhận xét bài làm trong buổi.","keyTopics":["Phân tích đề","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":2,"title":"Lập dàn ý","description":"Học và thực hành lập dàn ý; gia sư nhận xét bài làm trong buổi.","keyTopics":["Lập dàn ý","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":3,"title":"Phát triển đoạn văn","description":"Học và thực hành phát triển đoạn văn; gia sư nhận xét bài làm trong buổi.","keyTopics":["Phát triển đoạn văn","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":4,"title":"Sửa bài theo band descriptor","description":"Học và thực hành sửa bài theo band descriptor; gia sư nhận xét bài làm trong buổi.","keyTopics":["Sửa bài theo band descriptor","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":5,"title":"Phân tích đề","description":"Học và thực hành phân tích đề; gia sư nhận xét bài làm trong buổi.","keyTopics":["Phân tích đề","Bài tập có phản hồi"],"durationMinutes":90},{"sessionIndex":6,"title":"Lập dàn ý","description":"Học và thực hành lập dàn ý; gia sư nhận xét bài làm trong buổi.","keyTopics":["Lập dàn ý","Bài tập có phản hồi"],"durationMinutes":90}]'::jsonb, '[{"qu