    ('3f316631-a9ee-5791-8a4a-32da3950a435', 'c8e6e19b-5646-5494-97ca-4661d908f4e6', '2ba182f2-0882-5249-8c91-ae8452ae592c', 'Đọc hiểu và ghi chép hiệu quả', 'Lộ trình 4 buổi học 1 kèm 1 về Phương pháp tự học. Mỗi buổi gồm ôn kiến thức, thực hành và nhận xét bài làm. Gia sư Ngô Hải Nam điều chỉnh bài tập theo điểm mạnh, điểm cần cải thiện của học viên.', 'Đọc có câu hỏi; Ghi chép Cornell; Tóm tắt ý chính; Tự kiểm tra kiến thức', 'Nắm được đọc có câu hỏi và tự xử lý bài tập tổng hợp trong phạm vi khóa học.', 4, 60, 800000, 'Both', NULL, 'Published', CURRENT_TIMESTAMP + INTERVAL '-154080 minutes', CURRENT_TIMESTAMP + INTERVAL '-57600 minutes', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80', '[{"sessionIndex":1,"title":"Đọc có câu hỏi","description":"Học và thực hành đọc có câu hỏi; gia sư nhận xét bài làm trong buổi.","keyTopics":["Đọc có câu hỏi","Bài tập có phản hồi"],"durationMinutes":60},{"sessionIndex":2,"title":"Ghi chép Cornell","description":"Học và thực hành ghi chép cornell; gia sư nhận xét bài làm trong buổi.","keyTopics":["Ghi chép Cornell","Bài tập có phản hồi"],"durationMinutes":60},{"sessionIndex":3,"title":"Tóm tắt ý chính","description":"Học và thực hành tóm tắt ý chính; gia sư nhận xét bài làm trong buổi.","keyTopics":["Tóm tắt ý chính","Bài tập có phản hồi"],"durationMinutes":60},{"sessionIndex":4,"title":"Tự kiểm tra kiến thức","description":"Học và thực hành tự kiểm tra kiến thức; gia sư nhận xét bài làm trong buổi.","keyTopics":["Tự kiểm tra kiến thức","Bài tập có phản hồi"],"durationMinutes":60}]'::jsonb, '[{"question":"Có cần chuẩn bị trước buổi học không?","answer":"Học viên gửi mục tiêu và bài đã làm để gia sư chuẩn bị nội dung phù hợp."},{"question":"Có thể đổi lịch không?","answer":"Có thể thống nhất lại lịch trực tiếp với gia sư trước buổi học."}]'::jsonb, '["Có thiết bị hoặc không gian học phù hợp","Sẵn sàng làm bài tập sau mỗi buổi"]'::jsonb, '["Học viên muốn củng cố Phương pháp tự học","N