INSERT INTO "Reviews" ("Id", "EnrollmentId", "Rating", "Comment", "TutorReply", "TutorRepliedAt", "IsRemoved", "RemovalReason", "RemovedAt", "RemovedByAdminId", "CreatedAt") VALUES
    ('69603171-711e-5a4e-9bb2-893318f66027', 'b711f898-f548-5c65-be57-f2c105fc33ab', 5, 'Gia sư giải thích từng bước và chỉ rõ lỗi trong bài làm; em tự làm được dạng tương tự sau khóa học. Nội dung em nhớ nhất là hàm số và đồ thị.', 'Cảm ơn Nguyễn Gia Bảo đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-115200 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-116640 minutes'),
    ('5f231f31-b85f-5fcc-a038-103bb9fa0e75', '3dc032e3-1be4-5438-867e-b7f1640d64f7', 5, 'Lộ trình bám sát mục tiêu ban đầu. Phần bài tập sau buổi học giúp em nhớ kiến thức lâu hơn. Nội dung em nhớ nhất là bảo toàn electron.', 'Cảm ơn Trần Khánh Huyền đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-129600 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-131040 minutes'),
    ('0b3f29ab-c772-5353-b1de-ab10c5766e1d', '293b5dc6-fe90-583f-bfd5-c42c02db1f07', 5, 'Thầy cô đúng giờ, chuẩn bị ví dụ phù hợp. Em thích cách nhận xét cụ thể thay vì chỉ đưa đáp án. Nội dung em nhớ nhất là giai đoạn 1954–1975.', NULL, NULL, FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-105120 minutes'),
    ('11e53162-29ea-5ed2-b14c-f2b8e198310e', '2924236f-94ee-52d5-93b7-37e3930f4c19', 4, 'Nội dung học hữu ích, nhưng em muốn có thêm bài luyện ở phần cuối khóa. Nội dung em nhớ nhất là chiến lược phân bổ thời gian.', 'Cảm ơn Phạm Ngọc Diệp đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-118080 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-119520 minutes'),
    ('d7bdd603-c7c6-5cf1-86d4-2b0c8cc7558f', 'fca65ff3-da19-5a7b-9522-c53b8e810e5c', 5, 'Gia sư giải thích từng bước và chỉ rõ lỗi trong bài làm; em tự làm được dạng tương tự sau khóa học. Nội dung em nhớ nhất là đọc hiểu.', 'Cảm ơn Hoàng Tuấn Kiệt đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-92160 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-93600 minutes'),
    ('6f29d939-3ca8-53ce-80c0-aca51f6f49f6', 'f0130119-a621-5bd1-bd64-8f2d6cb425de', 5, 'Lộ trình bám sát mục tiêu ban đầu. Phần bài tập sau buổi học giúp em nhớ kiến thức lâu hơn. Nội dung em nhớ nhất là quan hệ nguyên nhân–kết quả.', NULL, NULL, FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-108000 minutes'),
    ('22cebce4-8477-530b-be4d-7023d57d6e50', '2187f072-6285-5b76-8b40-0d9d4d2dd183', 5, 'Thầy cô đúng giờ, chuẩn bị ví dụ phù hợp. Em thích cách nhận xét cụ thể thay vì chỉ đưa đáp án. Nội dung em nhớ nhất là phát triển đoạn văn.', 'Cảm ơn Đặng Quỳnh Anh đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-80640 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-82080 minutes'),
    ('c6b486e0-35a3-5c36-b176-3ca909f7fe04', '7bd4be21-5c54-5ac1-a78d-5d4c26540050', 5, 'Nội dung học hữu ích, nhưng em muốn có thêm bài luyện ở phần cuối khóa. Nội dung em nhớ nhất là thực hành và sửa bài.', 'Cảm ơn Bùi Nhật Minh đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-95040 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-96480 minutes'),
    ('e8006b99-33a9-5622-a66a-566d50b456e5', '128cdf28-a3b8-5f24-b589-9325de822eaf', 4, 'Gia sư giải thích từng bước và chỉ rõ lỗi trong bài làm; em tự làm được dạng tương tự sau khóa học. Nội dung em nhớ nhất là cấu trúc html.', NULL, NULL, FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-70560 minutes'),
    ('01bde5ac-5fb0-5f36-bbc8-3bdd295b67b5', 'bf2d6e9a-a94d-5159-9d5c-9cca6d7876b5', 5, 'Lộ trình bám sát mục tiêu ban đầu. Phần bài tập sau buổi học giúp em nhớ kiến thức lâu hơn. Nội dung em nhớ nhất là kể chuyện part 2.', 'Cảm ơn Đỗ Phúc An đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-83520 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-84960 minutes'),
    ('75b22bab-045e-5daf-9855-7286a32cc3dd', '7d300bcc-4d32-51c8-8e48-d0f190099bd7', 5, 'Thầy cô đúng giờ, chuẩn bị ví dụ phù hợp. Em thích cách nhận xét cụ thể thay vì chỉ đưa đáp án. Nội dung em nhớ nhất là hàm và tệp.', 'Cảm ơn Mai Hà Phương đã học đều và gửi bài tập đúng hẹn. Chúc em tiếp tục giữ nhịp tự học!', CURRENT_TIMESTAMP + INTERVAL '-57600 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-59040 minutes'),
    ('586bb7cc-9ec7-5bca-aa5b-83a200cbe6dd', '203d7766-9b3e-5d36-bb24-8dbff74aa1cc', 5, 'Nội dung học hữu ích, nhưng em muốn có thêm bài luyện ở phần cuối khóa. Nội dung em nhớ nhất là dự án danh sách công việc.', NULL, NULL, FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-73440 minutes');
