INSERT INTO "Messages" ("Id", "ConversationId", "SenderUserId", "Content", "AttachmentKey", "AttachmentName", "AttachmentContentType", "AttachmentSize", "IsRead", "ReadAt", "CreatedAt") VALUES
    ('36bdf42b-8a07-553c-acc5-8d7197b8ddd6', '92530b36-2931-5bad-aa4d-706be34c60a1', 'a90f991b-761a-595d-8194-51d21e47a5d9', 'Chào Nguyễn Minh Anh, em đang xem gói Giải tích 12 từ nền tảng đến vận dụng. Em đang bị hổng phần nền tảng; thầy/cô có thể khảo sát trước buổi đầu không ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-182860 minutes', CURRENT_TIMESTAMP + INTERVAL '-182880 minutes'),
    ('066ba27c-0dfe-5bf3-80ff-af20757aea39', '92530b36-2931-5bad-aa4d-706be34c60a1', 'fe2f8134-8468-5fe1-b914-ad73accbe890', 'Được em nhé. Trước buổi đầu em gửi một bài gần đây, mình sẽ xem điểm mạnh và phần cần ôn lại.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-182805 minutes', CURRENT_TIMESTAMP + INTERVAL '-182825 minutes'),
    ('7db7d808-47ce-52fd-a29c-eb549deaed93', '92530b36-2931-5bad-aa4d-706be34c60a1', 'a90f991b-761a-595d-8194-51d21e47a5d9', 'Dạ em cảm ơn Anh. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, FALSE, NULL, CURRENT_TIMESTAMP + INTERVAL '-182790 minutes'),
    ('c5999391-4d8c-51f3-b74d-e0ac8625d908', '4e2fb6d4-c6a4-587d-9c85-15fa1e8248ba', '89c9bb82-ae8f-5c75-956b-a77d2b552910', 'Chào Phạm Bảo Ngọc, em đang xem gói Bài tập định lượng Hóa 12. Em muốn biết phần bài tập sau mỗi buổi sẽ được nhận xét như thế nào ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-177100 minutes', CURRENT_TIMESTAMP + INTERVAL '-177120 minutes'),
    ('118faabd-38a5-5c7e-b027-c7396a04b9cf', '4e2fb6d4-c6a4-587d-9c85-15fa1e8248ba', '1c138fa6-b36c-501f-86e4-4aafddcd3f2d', 'Sau mỗi buổi mình gửi bài vừa sức và ghi nhận xét ở những câu em làm sai để em sửa từng bước.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-177045 minutes', CURRENT_TIMESTAMP + INTERVAL '-177065 minutes'),
    ('1df76142-7f98-56e3-8b59-52aa4dfada98', '4e2fb6d4-c6a4-587d-9c85-15fa1e8248ba', '89c9bb82-ae8f-5c75-956b-a77d2b552910', 'Dạ em cảm ơn Ngọc. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-177010 minutes', CURRENT_TIMESTAMP + INTERVAL '-177030 minutes'),
    ('8d621c8f-6412-5870-8735-24c030274216', '5a0da82c-0b46-5ca3-813c-1fbb0ee2838e', '74f9e878-051a-574d-bf35-f243daf00ee9', 'Chào Hoàng Đức Phúc, em đang xem gói Lịch sử Việt Nam 1945–1975 theo chủ đề. Em học vào buổi tối trong tuần; mình có thể thống nhất lịch trước khi bắt đầu không ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-171340 minutes', CURRENT_TIMESTAMP + INTERVAL '-171360 minutes'),
    ('3ec6a733-d882-58ee-803a-a8bac773e0c7', '5a0da82c-0b46-5ca3-813c-1fbb0ee2838e', '778ca838-d8f4-5d60-8349-761e31ce0389', 'Mình có thể trao đổi lịch buổi tối. Em nhắn hai khung giờ thuận tiện để cùng chốt nhé.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-171285 minutes', CURRENT_TIMESTAMP + INTERVAL '-171305 minutes'),
    ('bbe1b2c0-892c-5042-8a1b-36c1f06115c8', '5a0da82c-0b46-5ca3-813c-1fbb0ee2838e', '74f9e878-051a-574d-bf35-f243daf00ee9', 'Dạ em cảm ơn Phúc. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-171250 minutes', CURRENT_TIMESTAMP + INTERVAL '-171270 minutes'),
    ('94ee029a-1838-5870-8dba-eab489665aea', 'd7962463-9658-5fc9-8fcc-c493929ea4f7', 'cdced5db-0ddd-5d12-8b40-c56bc544e9ae', 'Chào Nguyễn Minh Anh, em đang xem gói Ôn thi tốt nghiệp THPT môn Toán. Em chuẩn bị thi trong vài tháng nữa, khóa học có thể ưu tiên dạng bài em hay sai không ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-165580 minutes', CURRENT_TIMESTAMP + INTERVAL '-165600 minutes'),
    ('7622b838-b828-5ba1-9048-67b98bfb58be', 'd7962463-9658-5fc9-8fcc-c493929ea4f7', 'fe2f8134-8468-5fe1-b914-ad73accbe890', 'Được em. Mình sẽ ưu tiên phần em hay mất điểm và dành một buổi cuối để luyện đề tổng hợp.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-165525 minutes', CURRENT_TIMESTAMP + INTERVAL '-165545 minutes'),
    ('7877e0bd-7e95-5f56-9972-f6d528f8c2d5', 'd7962463-9658-5fc9-8fcc-c493929ea4f7', 'cdced5db-0ddd-5d12-8b40-c56bc544e9ae', 'Dạ em cảm ơn Anh. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-165490 minutes', CURRENT_TIMESTAMP + INTERVAL '-165510 minutes'),
    ('9c8572ba-4ab8-5f58-ab1b-e67f0969308e', '62d4e758-c6c2-5e03-967e-fec7cfdeba2e', '69396be3-87f3-5acc-920a-0f94fd36a236', 'Chào Đỗ Thanh Tâm, em đang xem gói Nghị luận xã hội và văn học vào lớp 10. Em đang bị hổng phần nền tảng; thầy/cô có thể khảo sát trước buổi đầu không ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-159820 minutes', CURRENT_TIMESTAMP + INTERVAL '-159840 minutes'),
    ('633312d0-9eb5-51ce-ac54-41393f880ab8', '62d4e758-c6c2-5e03-967e-fec7cfdeba2e', 'dc0a1d1e-a5c8-5146-92ee-258a848aa7bf', 'Được em nhé. Trước buổi đầu em gửi một bài gần đây, mình sẽ xem điểm mạnh và phần cần ôn lại.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-159765 minutes', CURRENT_TIMESTAMP + INTERVAL '-159785 minutes'),
    ('3b2464e1-0b42-589d-92f9-1ee0879525fd', '62d4e758-c6c2-5e03-967e-fec7cfdeba2e', '69396be3-87f3-5acc-920a-0f94fd36a236', 'Dạ em cảm ơn Tâm. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, FALSE, NULL, CURRENT_TIMESTAMP + INTERVAL '-159750 minutes'),
    ('de4ebbe4-ee4a-5578-9594-fec98ae74fc8', 'a1554314-a6b0-582f-a74e-8f7486fe58d2', '68a674c1-fac5-59fe-ac6a-0346d56948e6', 'Chào Hoàng Đức Phúc, em đang xem gói Ôn tập Lịch sử 12 bằng trục thời gian. Em muốn biết phần bài tập sau mỗi buổi sẽ được nhận xét như thế nào ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-154060 minutes', CURRENT_TIMESTAMP + INTERVAL '-154080 minutes'),
    ('fd22bf74-cde5-5cdb-b3a2-6e7061c7f10c', 'a1554314-a6b0-582f-a74e-8f7486fe58d2', '778ca838-d8f4-5d60-8349-761e31ce0389', 'Sau mỗi buổi mình gửi bài vừa sức và ghi nhận xét ở những câu em làm sai để em sửa từng bước.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-154005 minutes', CURRENT_TIMESTAMP + INTERVAL '-154025 minutes'),
    ('e1121686-05a9-5144-bb1a-f7e51bd03d82', 'a1554314-a6b0-582f-a74e-8f7486fe58d2', '68a674c1-fac5-59fe-ac6a-0346d56948e6', 'Dạ em cảm ơn Phúc. Em sẽ gửi bài và xác nhận lịch trước buổi học ạ.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-153970 minutes', CURRENT_TIMESTAMP + INTERVAL '-153990 minutes'),
    ('97698c68-d3b0-5da1-8329-815b1c4d6bf7', '554be810-68b6-566d-a26c-4572fe60e622', 'd4251b85-e96c-599e-b0cb-dc3b742b52df', 'Chào Trần Thu Hà, em đang xem gói IELTS Writing Task 2: lập luận và sửa bài. Em học vào buổi tối trong tuần; mình có thể thống nhất lịch trước khi bắt đầu không ạ?', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-148300 minutes', CURRENT_TIMESTAMP + INTERVAL '-148320 minutes'),
    ('e07f011b-fe47-520f-84f9-1b22b53ea707', '554be810-68b6-566d-a26c-4572fe60e622', '5a5640d4-8316-5de3-91e6-12f78bd512ad', 'Mình có thể trao đổi lịch buổi tối. Em nhắn hai khung giờ thuận tiện để cùng chốt nhé.', NULL, NULL, NULL, NULL, TRUE, CURRENT_TIMESTAMP + INTERVAL '-148245 minutes', CURRENT_TIMESTAMP + INTERVAL '-148265 minutes'),
