    ('3211c5c5-d65c-5cf9-995c-befd3e7e496c', 'ba979317-7f5e-5b5c-8f91-d3138f2041ee', '283ca06f-3334-5a58-93d1-9305c1db04ad', 'UserConduct', 'cacb3130-54af-5199-a47e-4d7053803289', '42194e77-afc1-548c-b6de-d0aa6e8e478c', 'Học viên phản ánh gia sư đến muộn; bộ phận hỗ trợ đang đối chiếu lịch học.', NULL, 'Open', NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-5760 minutes', NULL),
    ('15cdedc2-c67e-59a0-881e-81cf38604b0f', '087d4c64-ec8e-5466-9b34-5292fcabb3c2', NULL, 'General', '33aeba98-46c6-56a9-ac70-a39ef6396368', '68a674c1-fac5-59fe-ac6a-0346d56948e6', 'Học viên cần hướng dẫn tìm lịch buổi tiếp theo trong tài khoản.', NULL, 'Resolved', 'Dismissed', 'Đã hướng dẫn học viên xem mục Buổi học.', 'a8eb1e38-247d-53cb-938d-9a23e92615dc', CURRENT_TIMESTAMP + INTERVAL '-4320 minutes', CURRENT_TIMESTAMP + INTERVAL '-1440 minutes');
INSERT INTO "LearningRecords" ("Id", "SessionId", "TutorProfileId", "Content", "CreatedAt") VALUES
    ('cd719f03-e43f-5b2c-a159-d02117044fe0', '3927f8b8-5e8f-5426-a457-4a9efab56ea8', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 1 – Hàm số và đồ thị. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về hàm số và đồ thị trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-169890 minutes'),
    ('a23da070-ed43-50c3-9ac9-3a553f31c2ec', '07dd8f43-1e7f-53e1-8da6-aab14bafb60b', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 2 – Nguyên hàm, tích phân. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về nguyên hàm, tích phân trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-159810 minutes'),
    ('bed0a568-528f-559b-adad-af65ae725acb', 'c802480f-cba9-5da7-9a05-1e37950af380', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 3 – Ứng dụng đạo hàm. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về ứng dụng đạo hàm trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-149730 minutes'),
    ('ab0d905c-0dc4-50ae-bfb3-689ee7077d08', 'e5771534-080b-5e39-8d4b-9bccd1daafe1', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 4 – Luyện đề theo lỗi sai. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về luyện đề theo lỗi sai trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-139650 minutes'),
    ('bf2c48df-ac8a-598e-b27e-42f8582c08dc', 'a30f90c5-90c8-5c1a-a714-a48c13950c3b', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 5 – Hàm số và đồ thị. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về hàm số và đồ thị trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-129570 minutes'),
    ('779a2b49-d1de-5797-a7fb-c00d2bb6946c', '8bb8e065-0646-523e-93c2-4adf4754296e', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 6 – Nguyên hàm, tích phân. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về nguyên hàm, tích phân trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-119490 minutes'),
    ('c557b6fb-2593-5b31-aec5-483b4acf4f93', '19bbcb3b-c2f0-5fb4-8bb2-fe524012a4f0', '9ef29172-fa2a-5d8f-9f2a-5994f77d8806', 'Buổi 1 – Bảo toàn khối lượng. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về bảo toàn khối lượng trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-164130 minutes'),
    ('984810ab-e6e6-5cb6-aa3c-1ce89c58224e', 'b7935497-01b6-5220-ad33-79c1bf0d7fff', '9ef29172-fa2a-5d8f-9f2a-5994f77d8806', 'Buổi 2 – Bảo toàn electron. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về bảo toàn electron trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-154050 minutes'),
    ('ee22a1ca-579a-526e-a811-e103982f16c3', 'ba285f70-06a1-59f1-9e50-d492056f2567', '9ef29172-fa2a-5d8f-9f2a-5994f77d8806', 'Buổi 3 – Đồ thị thí nghiệm. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về đồ thị thí nghiệm trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-143970 minutes'),
    ('7202ccb4-b22d-5932-be2f-e2ca3010df21', '55f0bbc4-9672-5253-a550-40374f33b959', '9ef29172-fa2a-5d8f-9f2a-5994f77d8806', 'Buổi 4 – Luyện đề. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về luyện đề trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-133890 minutes'),
    ('79db810b-0f6e-506b-bef3-3c156d13866c', '6d3ea361-d473-54ac-a154-47916271103e', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 1 – Bối cảnh 1945. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về bối cảnh 1945 trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-158370 minutes'),
    ('142c8b3f-73fc-5703-8769-7673d4d24ea9', '6f40d7f4-ff85-570b-b5e2-944c60c2ae5e', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 2 – Kháng chiến chống Pháp. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về kháng chiến chống pháp trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-148290 minutes'),
    ('dcb83405-b592-5285-bef2-2ba61e3995b8', '3616eafe-a6cf-5726-976a-9c527b49aee9', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 3 – Giai đoạn 1954–1975. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về giai đoạn 1954–1975 trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-138210 minutes'),
    ('7725ecc3-3d40-53d3-a921-2ba05a376a6e', '274b1011-5df4-5ebb-abe0-9e79138a16fd', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 4 – So sánh sự kiện. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về so sánh sự kiện trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-128130 minutes'),
    ('72ab856f-2745-5866-84f0-0f283275c55b', 'c89055f9-fa12-5a2e-be94-badcc10916c1', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 5 – Bối cảnh 1945. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về bối cảnh 1945 trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-118050 minutes'),
    ('fd24e335-3317-5df0-ac3e-ca4e58eb7df0', '9cb35017-6caa-510e-a8a5-310128fda220', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 6 – Kháng chiến chống Pháp. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về kháng chiến chống pháp trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-107970 minutes'),
    ('047b6a72-b901-5c26-afd9-e7beb343b46d', '0f315f06-3389-5f64-babc-4c231ba489de', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 1 – Khảo sát năng lực. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về khảo sát năng lực trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-152610 minutes'),
    ('ebd044e7-7576-5b19-92ab-cc0df8683dd7', '24582211-5647-5c40-84b8-1ddf7790277a', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 2 – Các dạng vận dụng. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về các dạng vận dụng trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-142530 minutes'),
    ('5bad4f89-6cc4-5770-a76e-259a4d9199e1', 'a79fa2d7-923c-5386-a751-61970bec3682', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 3 – Đề minh họa. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về đề minh họa trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-132450 minutes'),
    ('b1a0fcb1-316d-574b-8b59-7bfef7aa6bdf', 'b030abe7-a1b9-5470-84d0-c434e81b7e10', 'abbc88f4-61fe-5451-8079-5ed54d9e6a47', 'Buổi 4 – Chiến lược phân bổ thời gian. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về chiến lược phân bổ thời gian trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-122370 minutes'),
    ('f4f358b4-2039-5c3f-8ce1-49a726d26318', '0cec5670-aab7-5d76-b909-754c7a731bef', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 1 – Đọc hiểu. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về đọc hiểu trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-146850 minutes'),
    ('847f698b-0946-598d-b14a-b4bc2027f1ed', '939f464a-ab05-5bf0-90e3-ef682336f1e9', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 2 – Lập luận xã hội. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về lập luận xã hội trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-136770 minutes'),
    ('cfabe20e-978a-535a-bc73-041823c7520c', 'eae0db68-bb2e-53a7-900f-e0a7c15b1611', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 3 – Phân tích tác phẩm. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về phân tích tác phẩm trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-126690 minutes'),
    ('fc8b692a-1ce5-591c-b3f6-348d6b348799', '71035e53-4bf1-59d2-a2c1-94aaaa3136a9', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 4 – Chỉnh sửa bài viết. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về chỉnh sửa bài viết trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-116610 minutes'),
    ('b4636a05-c1e0-5e84-8d91-d6e79899df9c', '4ef9165a-d32b-5e64-bc2b-98e908248ea4', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 5 – Đọc hiểu. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về đọc hiểu trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-106530 minutes'),
    ('28999217-c62d-5360-a215-501578ae4db2', '643b7bb6-8ca5-589e-9271-3137d1245f80', '41695a2d-64dd-50a3-9496-33f64306aa19', 'Buổi 6 – Lập luận xã hội. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về lập luận xã hội trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-96450 minutes'),
    ('de3360f8-a5cf-5e0f-ae41-0e40af6760e1', '9deba1b8-ec5d-5cd2-b045-6d90dc70705c', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 1 – Mốc thời gian. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về mốc thời gian trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-141090 minutes'),
    ('2a9644f1-2567-5496-aafd-39f267f269ff', '371ef62d-6035-5fb0-936f-6dd99c8c8a50', '94fee594-7505-5e77-9ab5-3bb0bce0368e', 'Buổi 2 – Quan hệ nguyên nhân–kết quả. Học viên đã hoàn thành bài tập trên lớp và được sửa các bước còn nhầm lẫn. Tự ôn: làm lại hai bài về quan hệ nguyên nhân–kết quả trước buổi sau.', CURRENT_TIMESTAMP + INTERVAL '-131010 minutes');
