    ('d72278bb-84f7-5b14-b207-f4dcc9b7b3a0', 'a90f991b-761a-595d-8194-51d21e47a5d9', 'Thanh toán gói học thành công', 'Gói Giải tích 12 từ nền tảng đến vận dụng với gia sư Nguyễn Minh Anh đã được kích hoạt.', 'PaymentSucceeded', '/bookings/f7a57899-06e9-57c2-ad59-c9a61aa58cdd', TRUE, CURRENT_TIMESTAMP + INTERVAL '-178560 minutes', TRUE, '31fccec9-459d-51ff-b5c6-753c23e7e162', 'seed:payment:0', CURRENT_TIMESTAMP + INTERVAL '-179992 minutes'),
