-- TutorHub portable local demo dataset.
-- All people, contact details and payment references are fictional.
-- Every seeded user can log in with Test@123 (bcrypt work factor 12).
-- DEV/TEST ONLY: this file replaces domain data in the selected database.
-- Apply EF migrations first. External files, emails and payment calls are not forged.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
TRUNCATE TABLE "AuditLogs", "OutboxMessages", "EmailDeliveries", "Notifications", "RefreshTokens", "Reports", "DisputeEvidences", "Disputes", "LearningRecords", "Media", "ConversationAttachments", "Messages", "Conversations", "Reviews", "TopUpRequests", "WalletTransactions", "Withdrawals", "Transactions", "Sessions", "Enrollments", "Bookings", "Services", "TutorSubjects", "Subjects", "Categories", "Wallets", "TutorProfiles", "TutorApplications", "StudentProfiles", "Users", "IdempotencyRecords", "ExternalLogins" RESTART IDENTITY CASCADE;

-- Users: 37 coherent demo records

-- Categories: 7 coherent demo records

-- Subjects: 12 coherent demo records

-- TutorApplications: 12 coherent demo records

-- StudentProfiles: 24 coherent demo records

-- TutorProfiles: 10 coherent demo records

-- TutorSubjects: 10 coherent demo records

-- Services: 20 coherent demo records

-- Wallets: 34 coherent demo records

-- TopUpRequests: 20 coherent demo records

-- Bookings: 48 coherent demo records

-- Enrollments: 40 coherent demo records

-- Sessions: 196 coherent demo records

-- Transactions: 130 coherent demo records

-- Withdrawals: 6 coherent demo records

-- WalletTransactions: 116 coherent demo records

-- Reviews: 12 coherent demo records

-- Conversations: 20 coherent demo records

-- Messages: 60 coherent demo records

-- Disputes: 2 coherent demo records

-- Reports: 3 coherent demo records

-- LearningRecords: 28 coherent demo records

-- Notifications: 77 coherent demo records

-- AuditLogs: 12 coherent demo records

-- Fail the transaction if payment snapshots, session allocation or wallets drift.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Enrollments" e JOIN "Bookings" b ON b."Id"=e."BookingId" WHERE e."TotalPrice"<>b."TotalPrice" OR e."ServiceId"<>b."ServiceId" OR b."Status"<>'Paid') THEN RAISE EXCEPTION 'Seed enrollment/booking mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "Enrollments" e LEFT JOIN (SELECT "EnrollmentId", SUM("SessionPrice") amount, COUNT(*) quantity FROM "Sessions" GROUP BY "EnrollmentId") s ON s."EnrollmentId"=e."Id" WHERE s.amount<>e."TotalPrice" OR s.quantity<>e."TotalSessions") THEN RAISE EXCEPTION 'Seed session allocation mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "TutorProfiles" t JOIN "Wallets" w ON w."TutorProfileId"=t."Id" LEFT JOIN (SELECT e."TutorProfileId", SUM(s."SessionPrice") amount FROM "Sessions" s JOIN "Enrollments" e ON e."Id"=s."EnrollmentId" WHERE e."Status"='Active' AND s."Status" IN ('Unscheduled','Scheduled','AwaitingPayout') GROUP BY e."TutorProfileId") p ON p."TutorProfileId"=t."Id" WHERE w."PendingBalance"<>COALESCE(p.amount,0)) THEN RAISE EXCEPTION 'Seed tutor escrow mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "Wallets" w LEFT JOIN (SELECT "WalletId", SUM(CASE WHEN "Direction"='Credit' THEN "Amount" ELSE -"Amount" END) amount FROM "WalletTransactions" WHERE "Type"<>'WithdrawalSuccessSettlement' GROUP BY "WalletId") x ON x."WalletId"=w."Id" WHERE w."AvailableBalance"<>COALESCE(x.amount,0)) THEN RAISE EXCEPTION 'Seed available wallet balance mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "Wallets" w LEFT JOIN (SELECT "WalletId", SUM(CASE WHEN "Type"='WithdrawalDebit' THEN "Amount" ELSE -"Amount" END) amount FROM "WalletTransactions" WHERE "Type" IN ('WithdrawalDebit','WithdrawalSuccessSettlement','WithdrawalReversalCredit') GROUP BY "WalletId") x ON x."WalletId"=w."Id" WHERE w."WithdrawingBalance"<>COALESCE(x.amount,0)) THEN RAISE EXCEPTION 'Seed withdrawing wallet balance mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "Sessions" s LEFT JOIN (SELECT "SessionId", COUNT(*) quantity FROM "Transactions" WHERE "Type"='SessionPayoutCredit' GROUP BY "SessionId") p ON p."SessionId"=s."Id" WHERE (s."IsPayoutReleased" AND COALESCE(p.quantity,0)<>1) OR (NOT s."IsPayoutReleased" AND COALESCE(p.quantity,0)<>0)) THEN RAISE EXCEPTION 'Seed session payout mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM "Reviews" r JOIN "Enrollments" e ON e."Id"=r."EnrollmentId" WHERE e."Status"<>'Completed') THEN RAISE EXCEPTION 'Seed review on incomplete enrollment'; END IF;
  IF EXISTS (SELECT 1 FROM "Users" WHERE "PasswordHash" <> '$2a$12$RgC9Ej9dMFD5/9UMFkiuIeJrkHgQZ.zJ.ptOq6Jr5ppPBraS3kCR.') THEN RAISE EXCEPTION 'Seed password mismatch'; END IF;
END $$;
COMMIT;
